<script>
(function(){'use strict';
const root=document.getElementById('sls-incidents');if(!root)return;const data=JSON.parse(document.getElementById('sls-inc-data').textContent),modal=document.getElementById('sls-inc-modal'),body=document.getElementById('sls-inc-form-body'),form=document.getElementById('sls-inc-form'),submit=document.getElementById('sls-inc-submit');let opener=null,handler=null,busy=false;
function node(tag,attrs,text){const n=document.createElement(tag);Object.keys(attrs||{}).forEach(k=>{if(k==='class')n.className=attrs[k];else if(k==='checked')n.checked=!!attrs[k];else n.setAttribute(k,attrs[k]);});if(text!==undefined)n.textContent=text;return n;}
function id(){if(!window.crypto||!window.crypto.getRandomValues)throw Error('This browser cannot generate secure request identifiers. Use an up-to-date browser.');return Array.from(crypto.getRandomValues(new Uint8Array(16))).map(v=>v.toString(16).padStart(2,'0')).join('');}
function field(parent,label,control,help){const wrap=node('div',{class:'sls-inc-field'}),uid='inc-field-'+id();control.id=uid;wrap.append(node('label',{for:uid},label),control);if(help)wrap.append(node('span',{class:'sls-inc-help'},help));parent.append(wrap);return control;}
function input(value,max,required){const n=node('input',{type:'text',maxlength:String(max)});n.value=value||'';n.required=!!required;return n;}
function select(options,value){const n=node('select');options.forEach(row=>{const o=node('option',{value:row[0]},row[1]);o.selected=row[0]===value;n.append(o);});return n;}
function check(parent,label,value){const wrap=node('label',{class:'sls-inc-check'}),n=node('input',{type:'checkbox',checked:value});wrap.append(n,node('span',{},label));parent.append(wrap);return n;}
function status(message,inModal){const n=document.getElementById(inModal?'sls-inc-modal-status':'sls-inc-status');n.textContent=message;n.hidden=!message;}
function open(title,label,help){opener=document.activeElement;handler=null;body.replaceChildren();status('',true);document.getElementById('sls-inc-modal-title').textContent=title;document.getElementById('sls-inc-modal-help').textContent=help;submit.textContent=label;submit.disabled=false;modal.hidden=false;setTimeout(()=>{const first=body.querySelector('input,select,textarea,button');(first||submit).focus();},0);}
function close(){if(busy)return;modal.hidden=true;handler=null;if(opener&&opener.isConnected)opener.focus();}
root.querySelector('.sls-inc-close').addEventListener('click',close);root.querySelector('.sls-inc-cancel').addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close();});modal.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const items=Array.from(modal.querySelectorAll('button,input,select,textarea,a[href]')).filter(n=>!n.disabled&&n.offsetParent!==null);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
async function call(action,payload){const request=new URLSearchParams({slsmassnotifyserver_csrf:data.csrf,slsmassnotifyserver_action:action,payload:JSON.stringify(payload)});const abort=new AbortController(),timer=setTimeout(()=>abort.abort(),25000);try{const response=await fetch('config.php?display=slsmassnotifyserver_incidents',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:request,signal:abort.signal});let result;try{result=await response.json();}catch(e){throw Error('The PBX did not return a readable response. Keep this form and its request identifier; refresh the incident before sending again.');}if(!response.ok||!result.success)throw Error(result.message||'Incident request failed (HTTP '+response.status+').');return result;}finally{clearTimeout(timer);}}
function navigate(result){if(result.id)location.href='config.php?display=slsmassnotifyserver_incidents&incident_id='+encodeURIComponent(result.id);else location.reload();}
form.addEventListener('submit',async e=>{e.preventDefault();if(busy||!handler||!form.reportValidity())return;busy=true;submit.disabled=true;status('Saving the request and checking its result…',true);try{await handler();}catch(error){status(error.name==='AbortError'?'The request timed out before confirmation. Keep this form open and retry with its same request identifier, or inspect the incident. Do not create another send.':error.message,true);}finally{busy=false;submit.disabled=false;if(!modal.hidden)submit.focus();}});
function deliveryEditor(parent,current,title){current=current||{};const section=node('div',{class:'sls-inc-section'});section.append(node('h3',{},title));const grid=node('div',{class:'sls-inc-grid'});section.append(grid);parent.append(section);const controls={};[['extensions','Phone extensions'],['desktop_clients','Desktop clients'],['group_ids','Saved announcement groups'],['voice_recipient_ids','External voice recipients'],['webhook_ids','Webhook destinations'],['email_recipient_ids','Announcement email recipients'],['sms_recipient_ids','SMS recipients']].forEach(pair=>{const n=node('select',{multiple:'multiple','aria-label':pair[1]});(data.choices[pair[0]]||[]).forEach(row=>{const o=node('option',{value:row.id},row.name);o.selected=(current[pair[0]]||[]).includes(row.id);n.append(o);});(current[pair[0]]||[]).filter(value=>!(data.choices[pair[0]]||[]).some(row=>row.id===value)).forEach(value=>{const o=node('option',{value},'Unavailable saved target · '+value);o.selected=true;n.append(o);});controls[pair[0]]=field(grid,pair[1],n,'Select the exact intended audience. No selection means this channel is unused.');const wrap=n.parentElement,search=node('input',{type:'text',placeholder:'Find destinations…','aria-label':'Find '+pair[1]});search.style.marginBottom='7px';wrap.insertBefore(search,n);search.addEventListener('input',()=>Array.from(n.options).forEach(o=>o.hidden=!o.textContent.toLowerCase().includes(search.value.toLowerCase())));const actions=node('div',{class:'sls-inc-actions',style:'margin-top:7px'}),all=node('button',{type:'button',class:'btn btn-default btn-sm'},'Select visible'),clear=node('button',{type:'button',class:'btn btn-default btn-sm'},'Clear selection'),count=node('span',{class:'sls-inc-muted'});function recount(){count.textContent=n.selectedOptions.length+' selected';}all.addEventListener('click',()=>{Array.from(n.options).filter(o=>!o.hidden).forEach(o=>o.selected=true);recount();});clear.addEventListener('click',()=>{Array.from(n.options).forEach(o=>o.selected=false);recount();});n.addEventListener('change',recount);recount();actions.append(all,clear,count);wrap.append(actions);});controls.audio_mode=field(grid,'Phone audio',select([['none','No audio'],['tones','Tones only'],['tts','Speech only'],['tones_tts','Tones and speech']],current.audio_mode||'none'));['opening_tone','closing_tone'].forEach(key=>{controls[key]=field(grid,key==='opening_tone'?'Opening tone':'Closing tone',select([['','No tone']].concat(data.tones.map(t=>[t,t])),current[key]||''));});controls.style=field(grid,'Visual style',select([['standard','Plain text'],['colored','Colored announcement']],current.style||'standard'));const color=node('input',{type:'color'});color.value=current.background_color||'#1f2937';controls.background_color=field(grid,'Background color',color);return()=>{const out={};Object.keys(controls).forEach(key=>{out[key]=controls[key].multiple?Array.from(controls[key].selectedOptions).map(o=>o.value):controls[key].value;});return out;};}
function rowList(parent,title,columns,initial,max){const section=node('div',{class:'sls-inc-section'}),rows=node('div');section.append(node('h3',{},title),rows);const add=node('button',{type:'button',class:'btn btn-default btn-sm'},'Add row');section.append(add);parent.append(section);const entries=[];function create(value){if(entries.length>=max){status('This section supports at most '+max+' rows.',true);return;}const wrapper=node('div',{class:'sls-inc-row'+(columns.length>=3?' sls-inc-roster-row':'')}),entry={id:value.id||('person_'+id().slice(0,24)),controls:{},wrapper};columns.forEach(column=>{const control=column[0]==='location_id'?select([['','No delegated location']].concat((data.choices.locations||[]).map(r=>[r.id,r.name])),value[column[0]]||''):column[0]==='desktop_username'?select([['','Operator roll call only']].concat((data.choices.desktop_clients||[]).map(r=>[r.id,r.name])),value[column[0]]||''):input(value[column[0]],column[2],column[3]);control.setAttribute('aria-label',column[1]);control.setAttribute('placeholder',column[1]);entry.controls[column[0]]=control;wrapper.append(control);});const remove=node('button',{type:'button',class:'btn btn-default btn-sm','aria-label':'Remove '+title+' row'},'Remove');remove.addEventListener('click',()=>{entries.splice(entries.indexOf(entry),1);wrapper.remove();});wrapper.append(remove);entries.push(entry);rows.append(wrapper);}add.addEventListener('click',()=>create({}));initial.forEach(create);return()=>entries.map(entry=>{const row={id:entry.id};Object.keys(entry.controls).forEach(key=>row[key]=entry.controls[key].value.trim());return row;});}
