function editTemplate(template){const t=template||{id:'tpl_'+id().slice(0,24)};open(template?'Edit template':'New incident template','Save template','Template changes activate after Apply Config; existing incidents stay unchanged.');const grid=node('div',{class:'sls-inc-grid'});body.append(grid);const name=field(grid,'Template name',input(t.name,80,true)),title=field(grid,'Announcement title',input(t.title,80,true)),severity=field(grid,'Severity',select([['information','Information'],['warning','Warning'],['critical','Critical']],t.severity||'warning'));const message=node('textarea',{maxlength:'500',required:'required'});message.value=t.message||'';field(body,'Approved message',message,'Use {{field_key}} for required operator values, for example {{location}}. Rendered messages must remain within 500 characters.');const getLanguages=languageEditor(body,t.language_variants);const getResources=resourceEditor(body,t.resources);const getFields=rowList(body,'Required operator fields',[['key','field_key',32,true],['label','Question shown to sender',80,true]],t.fields||[],12),getDelivery=deliveryEditor(body,t.delivery,'Audience and channels'),getRoster=rowList(body,'Person roster',[['name','Person name',100,true],['location','Location',120,false],['desktop_username','Desktop identity',80,false],['location_id','Delegated location',64,false]],t.roster||[],1000);body.append(node('p',{class:'sls-inc-help'},'Assign a desktop only when it belongs to that person and is in the selected audience. Assign a saved location to delegate roll call for people without a desktop. Location labels alone do not grant warden access. Shared desktop receipts are not person-level responses.'));const checklist=node('textarea');checklist.value=(t.checklist||[]).join('\n');field(body,'Observer checklist',checklist,'One item per line; up to 25 items. Useful for drill observations and after-action review.');const getEscalation=escalationEditor(body,t.escalation);handler=async()=>{const payload={id:t.id||'',name:name.value.trim(),title:title.value.trim(),message:message.value.trim(),severity:severity.value,resources:getResources(),language_variants:getLanguages(),fields:getFields().map(({key,label})=>({key,label})),delivery:getDelivery(),roster:getRoster(),checklist:checklist.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean),escalation:getEscalation()};await call('save_template',payload);location.reload();};}
function startTemplate(templateId){const t=data.active_templates.find(row=>row.id===templateId);if(!t){status('This template has not been applied. Use Apply Config before launching.');return;}const pending=data.templates.find(row=>row.id===templateId);if(pending&&JSON.stringify(pending)!==JSON.stringify(t)){status('This template has unapplied changes. Use Apply Config before launching so the selected wording and audience match.');return;}open('Launch '+t.name,'Send initial announcement','Each send creates an immutable announcement. No recipients can be added to this incident afterward.');const language=field(body,'Message language',select([['','Default approved wording']].concat((t.language_variants||[]).map(v=>[v.locale,v.label+' · '+v.locale])),''),'One reviewed version goes to the complete audience. Speech uses a matching installed English, Spanish, French, German or Portuguese voice. Regional variants use the catalog accent. Review the preview; SLS does not translate it.');const request=id(),values={};t.fields.forEach(row=>values[row.key]=field(body,row.label,input('',120,true)));const drill=check(body,'Mark this incident and every follow-up as a drill / test',true),scheduled=check(body,'Schedule this drill instead of sending now',false),time=node('input',{type:'datetime-local'});time.step='1';const timeWrap=node('div');body.append(timeWrap);field(timeWrap,'Drill start (this browser’s local time)',time,'The exact timezone-aware instant is saved. Starts more than 15 minutes late are marked missed.');timeWrap.hidden=true;function flags(){scheduled.disabled=!drill.checked;if(!drill.checked)scheduled.checked=false;timeWrap.hidden=!scheduled.checked;time.required=scheduled.checked;submit.textContent=scheduled.checked?'Schedule drill':'Send initial announcement';}drill.addEventListener('change',flags);scheduled.addEventListener('change',flags);body.append(node('h3',{class:'sls-inc-section'},'Message preview'));const preview=node('div',{class:'sls-inc-preview'});body.append(preview);function render(){const chosen=(t.language_variants||[]).find(v=>v.locale===language.value)||t;let text=chosen.title+'\n\n'+chosen.message;Object.keys(values).forEach(key=>text=text.split('{{'+key+'}}').join(values[key].value||'['+key+']'));if(drill.checked){const separator=text.indexOf('\n\n');text='DRILL: '+text.slice(0,separator)+'\n\nDRILL / TEST. '+text.slice(separator+2);}preview.textContent=text;}Object.values(values).forEach(n=>n.addEventListener('input',render));drill.addEventListener('change',render);language.addEventListener('change',render);render();const count=Object.keys(t.delivery).filter(k=>Array.isArray(t.delivery[k])).map(k=>k.replace(/_/g,' ')+': '+t.delivery[k].length).join(' · ');body.append(node('p',{class:'sls-inc-help'},count));handler=async()=>{const fields={};Object.keys(values).forEach(key=>fields[key]=values[key].value);const payload={template_id:t.id,request_id:request,fields,is_test:drill.checked,language_variant:language.value};if(scheduled.checked)payload.planned_at=new Date(time.value).toISOString().replace(/\.\d{3}Z$/,'Z');navigate(await call('start_incident',payload));};}
const retentionButton=root.querySelector('#sls-inc-retention');if(retentionButton)retentionButton.addEventListener('click',()=>{open('Incident archival','Save archival settings','Apply Config activates this policy. Reports and replay identities remain permanent.');const current=data.retention,enabled=check(body,'Automatically archive old closed incidents and missed drills',current.enabled);const grid=node('div',{class:'sls-inc-grid'});body.append(grid);const days=node('input',{type:'number',min:'1',max:'3650',step:'1',required:'required'}),allocation=node('input',{type:'number',min:'64',max:'4096',step:'1',required:'required'});days.value=current.after_days;allocation.value=current.max_archive_mib;field(grid,'Age after last activity (days)',days,'Default 90. Open incidents and uncertain submissions are excluded.');field(grid,'Archive allocation (MiB)',allocation,'Default 256. Allow additional disk space for its journal and backup. Reports are never silently discarded.');handler=async()=>{await call('save_retention',{enabled:enabled.checked,after_days:Number(days.value),max_archive_mib:Number(allocation.value)});location.reload();};});
root.querySelector('#sls-inc-new').addEventListener('click',()=>editTemplate(null));root.querySelectorAll('[data-edit-template]').forEach(n=>n.addEventListener('click',()=>editTemplate(data.templates.find(t=>t.id===n.dataset.editTemplate))));root.querySelectorAll('[data-start-template]').forEach(n=>n.addEventListener('click',()=>startTemplate(n.dataset.startTemplate)));root.querySelectorAll('[data-delete-template]').forEach(n=>n.addEventListener('click',()=>{open('Remove saved template','Remove template','Existing incidents and their histories remain available.');body.append(node('p',{},'Remove this template from the pending configuration? Apply Config will remove it from future launch choices.'));handler=async()=>{await call('delete_template',{template_id:n.dataset.deleteTemplate});location.reload();};}));
root.querySelectorAll('[data-update-kind]').forEach(n=>n.addEventListener('click',()=>{const kind=n.dataset.updateKind,request=id();open(kind==='all_clear'?'Send explicit all-clear':'Send separate incident update',kind==='all_clear'?'Send all-clear':'Send update','Uses the frozen original audience. Earlier announcements and their expiry times stay unchanged.');const message=node('textarea',{required:'required',maxlength:'500'});field(body,'New announcement text',message);handler=async()=>navigate(await call('send_update',{incident_id:data.incident_id,request_id:request,kind,message:message.value}));}));
root.querySelectorAll('[data-person-id]').forEach(n=>n.addEventListener('click',()=>{const request=id();open('Record response · '+n.dataset.personName,'Record human response','Your administrator identity is recorded separately from any desktop software receipt.');const response=field(body,'Human response',select([['received','Person confirms receipt'],['safe','Safe / accounted for'],['needs_assistance','Needs assistance'],['missing','Missing / not accounted for']],'safe')),note=node('textarea',{maxlength:'500'});field(body,'Optional observation',note);handler=async()=>navigate(await call('roll_call',{incident_id:data.incident_id,request_id:request,person_id:n.dataset.personId,response:response.value,note:note.value}));}));
root.querySelectorAll('[data-checklist-item]').forEach(n=>n.addEventListener('click',()=>{const request=id();open('Record observer result','Save observation','Observations remain attributable in the incident timeline.');body.append(node('p',{},n.dataset.checklistLabel));const complete=check(body,'Checklist item completed',true),note=node('textarea',{maxlength:'500'});field(body,'Observer note',note);handler=async()=>navigate(await call('observer_result',{incident_id:data.incident_id,request_id:request,item:Number(n.dataset.checklistItem),complete:complete.checked,note:note.value}));}));
const exportButton=root.querySelector('#sls-inc-export');if(exportButton)exportButton.addEventListener('click',async()=>{exportButton.disabled=true;try{let report=await call('export_report',{incident_id:data.incident_id}),pages=1;while(!report.complete){status('Collecting delivery report page '+(pages+1)+'…');const page=await call('export_report',{incident_id:data.incident_id,job_offset:report.next_job_offset,revision:report.revision});Object.keys(page.incident.operations).forEach(key=>{if(page.incident.operations[key].delivery)report.incident.operations[key]=page.incident.operations[key];});report.delivery_results_available=report.delivery_results_available&&page.delivery_results_available;report.complete=page.complete;report.next_job_offset=page.next_job_offset;if(++pages>250||JSON.stringify(report).length>33554432)throw Error('This report exceeds the browser export limit. Retrieve its bounded report pages through the Control API.');}report.page_count=pages;const encoded=JSON.stringify(report,null,2);if(encoded.length>33554432)throw Error('This report exceeds the browser export limit. Retrieve its bounded report pages through the Control API.');const url=URL.createObjectURL(new Blob([encoded],{type:'application/json'})),link=node('a',{href:url,download:data.incident_id+'-report.json'});document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status(report.delivery_results_available?'Complete incident report exported.':'Report exported. Some delivery histories were unavailable and are explicitly marked.');}catch(error){status(error.message);}finally{exportButton.disabled=false;}});
})();
